def backfill(apps, schema_editor):
    """Spec 19 §11.1: capitals, LGA slugs (unique within each state), and loads before 19 count as applied."""
    from django.utils.text import slugify

    from apps.geo.reference import CAPITALS

    State, Lga, Dataset = apps.get_model("geo", "State"), apps.get_model("geo", "Lga"), apps.get_model("geo", "Dataset")
    for st in State.objects.all():
        State.objects.filter(pk=st.pk).update(capital=CAPITALS.get(st.slug, ""))
        taken = set()
        for lga in Lga.objects.filter(state=st).order_by("code"):
            base = slugify(lga.name)[:80] or f"lga-{lga.code}"
            slug = base if base not in taken else f"{base}-{lga.code}"
            taken.add(slug)
            Lga.objects.filter(pk=lga.pk).update(slug=slug)
    for d in Dataset.objects.filter(applied_at__isnull=True):
        Dataset.objects.filter(pk=d.pk).update(applied_at=d.loaded_at)


